  "P/F/Cバーの色": "Màu thanh P/F/C",
  "たんぱく質・脂質・炭水化物をそれぞれ好きな色にできます。目標を超えたバーは赤で表示されます。": "Tùy chỉnh màu theo ý thích cho đạm, chất béo và tinh bột. Thanh vượt mục tiêu sẽ chuyển sang màu đỏ.",
