  "同じ色が重複しています。見分けにくくなるので別の色をおすすめします。": "Đang có màu bị trùng. Hãy chọn các màu khác nhau để dễ phân biệt hơn nhé.",
  "未翻訳の項目は日本語で表示されます。翻訳は順次追加していきます。": "Các mục chưa dịch sẽ hiển thị bằng tiếng Nhật. Bản dịch sẽ được cập nhật dần.",
  "＋ 食品を追加": "＋ Thêm thực phẩm",
  "この機能はTestFlight版で有効になります（Expo Goプレビューでは利用できません）。": "Tính năng này khả dụng trên bản TestFlight (không hỗ trợ trên bản xem trước Expo Go).",
  "Appleヘルスケアから体重を取り込みます。データは機能提供のみに使用し、広告等には一切使用しません。歩数・睡眠は「概要」タブで見られます。": "Nhập cân nặng từ Apple Health. Dữ liệu chỉ dùng để cung cấp tính năng, không bao giờ dùng cho quảng cáo. Số bước và giấc ngủ có thể xem ở tab Tổng quan.",
  "体重を取り込む（過去90日）": "Nhập cân nặng (90 ngày qua)",
  "チートデイの登録は「概要」タブのカードから行えます。": "Bạn có thể thêm cheat day từ thẻ ở tab Tổng quan.",
  "アカウントと全データ（記録・写真・目標・マイ食品）を完全に削除します。この操作は取り消せません。": "Thao tác này sẽ xóa vĩnh viễn tài khoản và toàn bộ dữ liệu (nhật ký, ảnh, mục tiêu, món ăn của tôi). Không thể hoàn tác.",
