  "ヘルスケアへのアクセスが許可されませんでした。iOSの設定 > プライバシー > ヘルスケア から許可できます。": "Chưa cấp quyền truy cập Health. Bạn có thể cấp quyền trong Cài đặt iOS > Quyền riêng tư > Sức khỏe.",
