  "分": "phút",
  "この記録の他の種目は残ります。": "Các bài tập khác trong mục này vẫn sẽ được giữ lại.",
  "入力欄に戻しました。直して保存すると置き換わります。": "Đã đưa về biểu mẫu. Hãy chỉnh sửa và lưu để cập nhật nhé.",
  "種目と回数を入力してください。（加重しない自重種目はkg空欄でOK）": "Vui lòng nhập bài tập và số lần. (Để trống kg nếu là bài tập tự trọng không tạ)",
  "保存しました。継続が最強の種目です💪": "Đã lưu. Kiên trì chính là bài tập mạnh mẽ nhất 💪",
  "🎉 目標達成！{name} 推定MAX {est}kg（目標{goal}kg超え）。次の目標を設定しよう": "🎉 Đạt mục tiêu rồi! {name} — ước tính MAX {est}kg (vượt mục tiêu {goal}kg). Hãy đặt mục tiêu tiếp theo nào",
  "おしい！RM換算だとMAX {est}kg。目標{goal}kgまであと{left}kg": "Tiếc quá! Quy đổi RM ước tính MAX {est}kg. Còn thiếu {left}kg nữa là đạt mục tiêu {goal}kg",
