  "確認メールを {mail} に送りました。メール内のリンクを開いてから、ログインしてください。": "Chúng tôi đã gửi email xác nhận đến {mail}. Vui lòng mở liên kết trong email rồi đăng nhập.",
  "Googleログインは準備中です（Supabase側のプロバイダ設定待ち）。": "Đăng nhập bằng Google đang được chuẩn bị (chờ thiết lập nhà cung cấp từ phía Supabase).",
