  "なんのために使う？": "Mục tiêu của bạn là gì?",
  "目的に合わせて、たんぱく質・脂質の目安を自動で決めます。あとで「設定→体重の目標」からいつでも変えられます。": "Chúng tôi sẽ tự động điều chỉnh mục tiêu đạm và chất béo cho phù hợp. Bạn có thể đổi lại bất cứ lúc nào trong Cài đặt → Mục tiêu cân nặng.",
  "目的はあとで決める": "Để sau",
  "目標を決める": "Đặt mục tiêu",
  "目標から逆算して、毎日の「あと食べられる量」を自動計算します。「目標を保存する」を押してから次へ進んでください。": "Chúng tôi sẽ tính toán lượng ăn còn lại mỗi ngày dựa trên mục tiêu của bạn. Hãy nhấn Lưu mục tiêu trước khi tiếp tục.",
  "次へ — 筋トレ目標（任意）": "Tiếp theo — Mục tiêu tập luyện (không bắt buộc)",
