  "ベンチプレス100kgのような目標を置くと、トレのグラフに目標線が出ます。筋トレをしない人はスキップでOKです。": "Đặt mục tiêu như đẩy ngực 100kg và đường mục tiêu sẽ hiện trên biểu đồ. Bỏ qua nếu bạn không tập tạ.",
