  "通勤で歩く・立ち仕事・犬の散歩など。運動は週1〜2回": "Đi bộ đi làm, công việc đứng, dắt chó đi dạo. Tập thể dục 1–2 lần/tuần",
  "よく動く": "Vận động vừa phải",
