  "何が聞ける？": "Tôi có thể hỏi gì?",
  "あなたの記録（食事・体重・運動・気分）を根拠に答えます。タップするとそのまま質問できます。": "Câu trả lời dựa trên nhật ký của bạn (bữa ăn, cân nặng, vận động và tâm trạng). Chạm vào câu bất kỳ để hỏi.",
  "聞きたいことを探す": "Tìm câu hỏi",
  "見つかりませんでした。そのまま自由に書いても答えられます。": "Không tìm thấy. Bạn cũng có thể tự nhập câu hỏi của riêng mình.",
  "3週間ほど記録が貯まると、食べすぎた日の前後に何が起きていたかを分析できます。": "Sau khoảng 3 tuần ghi chép, bạn có thể phân tích những gì diễn ra xung quanh những ngày ăn nhiều.",
