  "「{name} {kg}kg×{reps}回」→ RM換算でMAX {max}kg を目標に設定しました。": "「{name} {kg}kg × {reps} lần」→ Đã đặt mục tiêu mức tạ tối đa (RM quy đổi) là {max}kg.",
