  "※ 自重種目の達成判定は実負荷（体重＋加重）で見ます。目標も体重を含めた重量で入れてください。": "※ Bài tập dùng trọng lượng cơ thể sẽ tính theo tải trọng thực tế (cơ thể + tạ thêm). Vui lòng nhập mục tiêu đã bao gồm cả cân nặng.",
