  "記録はここに書くだけ": "Chỉ cần nhập ghi nhận vào đây",
  "「バナナと卵2個」のように書いて↑を押すと、AIが栄養を計算してトレイに載せます。写真でもOK。✓保存で確定です。": "Chỉ cần gõ như \"chuối và 2 quả trứng\" rồi nhấn ↑, AI sẽ tính dinh dưỡng và đưa vào khay. Dùng ảnh cũng được. Nhấn ✓ để lưu.",
  "運動の記録": "Ghi nhận vận động",
  "犬の散歩でもOK。種類と時間を選ぶだけで消費カロリーに反映されます。筋トレは上のセグメントで切り替え。": "Dắt chó đi dạo cũng tính. Chỉ cần chọn loại hình và thời lượng là calo tiêu hao sẽ được cập nhật. Đổi sang Tập gym ở thanh chọn phía trên.",
  "変化を見る": "Xem thay đổi",
  "体重や挙上重量の推移はここ。グラフはピンチで拡大、ドラッグで期間移動できます。": "Biến động cân nặng và mức tạ nằm ở đây. Dùng 2 ngón tay để phóng to, kéo để chuyển mốc thời gian trên biểu đồ.",
  "設定はここ": "Cài đặt ở đây",
