  "AIコーチ": "Huấn luyện viên AI",
  "迷ったらAIコーチへ。あなたの記録データを根拠にアドバイスします。": "Nếu còn phân vân, hãy hỏi AI. AI sẽ đưa ra lời khuyên dựa trên chính dữ liệu bạn đã ghi lại.",
  "スキップ ✕": "Bỏ qua ✕",
  "次へ": "Tiếp theo",
