  "1分で使い方をご案内します。": "Hướng dẫn nhanh cách dùng chỉ trong 1 phút.",
  "ツアーのあとに、あなたの現在地点と目標を一緒に設定しましょう。": "Sau phần hướng dẫn, chúng ta sẽ cùng thiết lập điểm xuất phát và mục tiêu của bạn nhé.",
  "ガイドを始める": "Bắt đầu hướng dẫn",
  "今はしない": "Để sau",
  "最近ちょっと停滞気味かも。食事に何か問題ある？": "Dạo này tiến độ hơi chững lại. Chế độ ăn của mình có vấn đề gì không?",
  "おすすめは「トレする日だけ白米を150g（+250kcal）足す」こと。週の収支はまだ赤字のままなので、減量ペースを崩さずパフォーマンスだけ取り戻せます。まずは次のトレ日に試してみましょう。": "Gợi ý cho bạn: \"chỉ thêm 150g cơm trắng (+250 kcal) vào những ngày có tập\". Mức thâm hụt calo cả tuần vẫn được duy trì, giúp bạn lấy lại phong độ mà không ảnh hưởng đến tốc độ giảm cân. Hãy thử vào buổi tập tới xem sao nhé.",
