  "体重は「7日平均」で見ると迷いません": "Theo dõi cân nặng theo trung bình 7 ngày để không bị hoang mang",
  "1日の上下は水分と食事のタイミングでほぼ説明できます。7日平均の傾きだけを見ると、判断を誤りにくくなります。": "Biến động hằng ngày chủ yếu do lượng nước và thời điểm ăn uống. Nhìn vào xu hướng trung bình 7 ngày sẽ giúp bạn đánh giá chuẩn xác hơn.",
  "睡眠不足の翌日は食欲ホルモンが増えます": "Thiếu ngủ làm tăng hormone thèm ăn vào hôm sau",
  "睡眠が短い日はグレリンが増え、レプチンが減ります。眠い日に食べたくなるのは意志の問題ではありません。": "Những ngày ngủ ít, ghrelin sẽ tăng và leptin giảm đi. Muốn ăn nhiều hơn khi mệt mỏi không phải là do bạn thiếu ý chí đâu.",
  "野菜から食べると血糖の波がゆるやかに": "Ăn rau trước giúp đường huyết ổn định hơn",
  "食物繊維が先に入ると糖の吸収が遅くなり、食後の眠気と空腹の反動が減ります。": "Bổ sung chất xơ trước sẽ làm chậm quá trình hấp thụ đường, giảm cảm giác buồn ngủ sau ăn và hạn chế đói cồn cào sau đó.",
  "筋トレ後のたんぱく質は24時間有効です": "Đạm sau tập vẫn có tác dụng suốt 24 giờ",
  "ゴールデンタイムは30分ではありません。トレ後1日は合成感度が高いので、その日の合計を厚くすれば十分です。": "\"Thời điểm vàng\" không chỉ gói gọn trong 30 phút. Độ nhạy tổng hợp cơ bắp kéo dài suốt 24 giờ sau tập, nên chỉ cần đảm bảo đủ tổng lượng trong ngày là được.",
  "{n}日連続で記録できています": "Bạn đã ghi chép {n} ngày liên tiếp",
  "記録の継続は、それ自体が成果です。完璧な内容である必要はなく、書いてある日が多いほどAIの分析も正確になります。": "Duy trì ghi chép đã là một thành quả rồi. Không cần phải quá hoàn hảo, càng có nhiều dữ liệu thì AI phân tích càng chính xác.",
  "食べすぎの{p}%が{d}曜日。今日は{d}曜日です": "{p}% số lần ăn quá đà rơi vào {d}. Hôm nay là {d}",
  "責める話ではなく、備えの話です。たんぱく質を先に厚めに摂っておくと、夜の食欲の波が小さくなります。": "Không phải để phán xét, mà là để chuẩn bị thôi. Nạp thêm chút đạm sớm hơn có thể giúp kiềm chế cơn thèm ăn vào buổi tối đấy.",
  "体重は3週間ほぼ横ばい。焦る場面ではありません": "Cân nặng đi ngang suốt 3 tuần. Không cần phải sốt ruột đâu",
  "脂肪が減っていても、水分とグリコーゲンで隠れやすい時期があります。摂取記録が守れているなら、続けるのが正解です。": "Dù mỡ đang giảm, vẫn có những giai đoạn bị che lấp bởi nước và glycogen. Nếu bạn vẫn duy trì đúng lượng ăn, hãy cứ tiếp tục nhé.",
  "この7日で約{n}kcalの貯金ができています": "Trong 7 ngày qua, bạn đã thâm hụt được khoảng {n} kcal rồi đấy",
  "脂肪1kgは約7,200kcal。数字はゆっくりでも、確実に進んでいます。": "1kg mỡ tương đương khoảng 7.200 kcal. Con số có thể thay đổi chậm, nhưng bạn chắc chắn đang tiến bộ.",
  "{title}（{n}分で読めます）": "{title} (Đọc trong {n} phút)",
  "　→ 相談タブの「読みもの」からどうぞ。": "→ Mời bạn xem tại mục \"Bài viết\" trong tab Tư vấn.",
  "データの取得に失敗しました。通信環境を確認してください。": "Không thể tải dữ liệu. Vui lòng kiểm tra lại kết nối mạng.",
  "この端末では共有シートを開けませんでした。": "Không thể mở bảng chia sẻ trên thiết bị này.",
  "エクスポートに失敗しました（{msg}）。": "Xuất dữ liệu thất bại ({msg}).",
  "食事（概算）": "Bữa ăn (ước tính)",
