  "この機能はTestFlight版でのみ使えます（Expo Goでは動きません）。": "Tính năng này chỉ khả dụng trên bản TestFlight (không hoạt động trên Expo Go).",
  "ヘルスケアの読み取りに失敗しました。許可設定を確認してください。": "Không thể đọc dữ liệu từ Sức khỏe. Vui lòng kiểm tra quyền truy cập.",
