  "ワークアウトの読み取りに失敗しました。許可設定を確認してください。": "Không thể đọc dữ liệu bài tập. Vui lòng kiểm tra quyền truy cập.",
  "{n}日連続で大きめの赤字（−300kcal超）が続いています": "Bạn đã thâm hụt calo khá lớn (hơn −300 kcal) trong {n} ngày liên tiếp",
  "あなたの過去の食べ過ぎは、平均{n}日連続赤字の後に起きています": "Trước đây, bạn thường ăn quá mức sau trung bình {n} ngày thâm hụt liên tiếp",
  "昨日は特に大きな赤字（−{n}kcal）でした": "Hôm qua bạn đã thâm hụt calo khá nhiều (−{n} kcal)",
  "たんぱく質が2日続けて不足気味です（食欲が乱れやすい状態）": "Lượng đạm đã bị thiếu 2 ngày liên tiếp (dễ làm rối loạn cảm giác thèm ăn đấy)",
  "過去の食べ過ぎの{p}%が{d}曜日に起きています": "{p}% những lần ăn quá mức trước đây diễn ra vào Thứ {d}",
