  "ケトルベルスイング": "Kettlebell swing",
  "今日の記録、忘れていませんか？": "Bạn có quên ghi chép hôm nay không?",
  "食べたものを1行書くだけでOK。続けるほどAIのアドバイスが賢くなります。": "Chỉ cần viết một dòng những gì bạn đã ăn. Càng ghi chép đều đặn, AI sẽ càng đưa ra lời khuyên thông minh hơn.",
  "週1回の体チェック📸": "Kiểm tra vóc dáng hàng tuần 📸",
  "同じ場所・同じポーズで1枚。「概要」タブの体の写真から記録できます。": "Chụp một bức ảnh tại cùng một vị trí và tư thế. Bạn có thể ghi lại từ mục Ảnh chụp cơ thể trong tab \"Tổng quan\".",
  "明日はチートデイ🍖": "Ngày xả hơi (cheat day) vào ngày mai 🍖",
  "今日は普段どおりでOK。明日は罪悪感なく楽しみましょう。前後の日で計画が自動調整されます。": "Hôm nay cứ ăn uống như bình thường nhé. Ngày mai hãy thoải mái tận hưởng mà không cần lo lắng — kế hoạch cho những ngày trước và sau sẽ tự động điều chỉnh.",
  "鶏むね肉・白身魚・ノンオイルツナ・無脂肪ヨーグルト": "ức gà, cá thịt trắng, cá ngừ đóng hộp không dầu và sữa chua không béo",
  "鶏肉・魚・卵・大豆製品": "thịt gà, cá, trứng và các sản phẩm từ đậu nành",
  "ごはん・パン・いも類・果物": "cơm, bánh mì, các loại khoai và trái cây",
  "今日は目標より{n}kcal多めです。1日では体脂肪になりません。水分と軽い散歩でリセットして、明日はたんぱく質多めから始めるのがおすすめです。": "Hôm nay bạn đã nạp nhiều hơn mục tiêu {n}kcal. Một ngày ăn nhiều không thể tạo thành mỡ thừa ngay đâu. Hãy uống nước và đi bộ nhẹ nhàng để cân bằng lại, và ngày mai nên bắt đầu với thực đơn nhiều protein hơn nhé.",
  "ほぼ目標どおりです（{n}kcal超過）。誤差の範囲なので気にしなくて大丈夫です。": "Gần như hoàn toàn đúng mục tiêu (vượt quá {n}kcal). Đây là mức chênh lệch nhỏ nên bạn không cần phải bận tâm đâu.",
  "今日はこれから。{foods}を毎食に入れると、あと{n}gのたんぱく質を無理なく達成できます。": "Ngày mới chỉ vừa bắt đầu. Hãy thêm {foods} vào mỗi bữa ăn để dễ dàng đạt được {n}g protein còn lại nhé.",
  "脂質と炭水化物": "chất béo và carbs",
  "{tight}はもう十分なので、追加するなら「低脂質・高たんぱく」の{foods}が向いています。たんぱく質はあと{n}gです。": "Bạn đã nạp đủ {tight} rồi, vì vậy nếu muốn ăn thêm thì {foods} ít béo, giàu protein sẽ là lựa chọn phù hợp. Bạn vẫn còn thiếu {n}g protein.",
  "たんぱく質があと{n}g残っています。{foods}を1品足すと、筋肉を守りながら満腹感も続きます。": "Bạn vẫn còn thiếu {n}g protein. Thêm một phần {foods} sẽ giúp bảo vệ cơ bắp và giữ cảm giác no lâu hơn.",
  "炭水化物があと{n}g残っています。少なすぎると力が出にくくなるので、{foods}で補うのがおすすめです。": "Bạn vẫn còn thiếu {n}g carbs. Nạp quá ít carbs sẽ khiến bạn dễ mất sức, hãy bổ sung thêm bằng {foods} nhé.",
  "脂質にまだ{n}gの余裕があります。ナッツ・オリーブオイル・青魚など質の良い脂質で摂るとホルモンバランスに役立ちます。": "Bạn vẫn còn dư {n}g chất béo. Hãy nạp từ các nguồn chất béo tốt như các loại hạt, dầu ô liu hoặc cá béo để hỗ trợ cân bằng nội tiết tố.",
  "今日のバランスはとても良い状態です。残り{n}kcalに無理に合わせる必要はありません。": "Sự cân bằng dinh dưỡng hôm nay của bạn rất tốt rồi. Không cần phải cố ăn cho đủ {n}kcal còn lại đâu.",
  "残り{k}kcal。たんぱく質あと{p}g・脂質あと{f}g・炭水化物あと{c}gが目安です。": "Còn lại {k}kcal. Mục tiêu tiếp theo là khoảng {p}g protein, {f}g chất béo và {c}g carbs.",
  "時間内に解析できませんでした。文章を短くするか、もう一度お試しください。": "Không thể hoàn thành phân tích trong thời gian quy định. Vui lòng viết ngắn lại hoặc thử lại sau.",
  "通信できませんでした。電波状況を確認してもう一度お試しください。": "Không thể kết nối. Vui lòng kiểm tra tín hiệu mạng và thử lại.",
  "解析に失敗しました。もう一度お試しください。": "Không thể phân tích. Vui lòng thử lại nhé.",
  "プランを見る →": "Xem gói dịch vụ →",
  "ありがとうございます！": "Xin cảm ơn!",
  "プランが有効になりました。": "Gói dịch vụ đã được kích hoạt.",
  "購入できませんでした": "Không thể thực hiện mua hàng",
  "復元できる購入が見つかりませんでした": "Không tìm thấy giao dịch mua nào để khôi phục",
