  "プラン": "Gói dịch vụ",
  "記録・グラフはずっと無料。AIをもっと使いたくなったら。": "Ghi chép & biểu đồ luôn miễn phí. Nâng cấp nếu bạn muốn dùng AI nhiều hơn.",
  "プランは準備中です。もうしばらくお待ちください。": "Gói dịch vụ đang được chuẩn bị. Vui lòng chờ trong giây lát.",
