  "今日の消費カロリーを記録": "Ghi nhận calo tiêu hao hôm nay",
  "犬の散歩でも立派な運動。記録すると消費カロリーを計算して、今日の「あと食べられる量」に自動で上乗せします。": "Ngay cả đi dạo với cún cũng là một hoạt động tuyệt vời. Hãy ghi lại để tự động tính lượng calo tiêu hao và cộng thêm vào lượng ăn cho phép hôm nay.",
  "とじる": "Đóng",
  "レストタイマー": "Hẹn giờ nghỉ",
