  "目標を記録しましょう": "Hãy ghi lại mục tiêu của bạn",
  "ベンチプレス100kgなど。成長グラフに目標線が引かれます。": "Ví dụ: Bench Press 100kg. Đường mục tiêu sẽ được hiển thị trên biểu đồ tiến trình.",
  "実重量ベースの最高記録（自重種目は体重込み）": "Kỷ lục cao nhất dựa trên trọng lượng thực tế (bao gồm cả trọng lượng cơ thể đối với các bài tập Bodyweight)",
  "継続": "Tiếp tục",
  "行動": "Hoạt động",
