  "🔥 ストリーク": "🔥 Chuỗi",
  "🍽 今日の食事": "🍽 Bữa ăn hôm nay",
  "🏃 最新の運動": "🏃 Bài tập gần đây",
  "🏆 自己ベスト": "🏆 Kỷ lục cá nhân",
  "実績": "Danh hiệu",
  "日連続": "ngày liên tiếp",
  "お守りが{d}の抜けをつなぎました（週1回まで自動）": "Bùa hộ mệnh đã giúp bạn duy trì chuỗi ngày {d} (tự động tối đa 1 lần/tuần)",
  "1日抜けても、週1回まで「お守り」が自動でつなぎます": "Dù bỏ lỡ 1 ngày, \"Bùa hộ mệnh\" sẽ tự động giúp bạn duy trì chuỗi (tối đa 1 lần/tuần)",
  "ストーリー用ステッカーを作る": "Tạo nhãn dán cho Tin",
  "文字だけの透過画像。自分の写真の上に重ねて、いつでも共有できます。": "Ảnh trong suốt chỉ có chữ. Bạn có thể chèn lên ảnh của mình và chia sẻ bất cứ lúc nào.",
  "{n} / {m} 個 獲得": "Đã đạt {n} / {m}",
  "{d} 獲得": "Đã đạt {d}",
  "ストリーク・バッジ・ストーリー共有": "Chuỗi, huy hiệu & chia sẻ Tin",
  "実重量ベースの最高記録（自重種目は体重込み）。共有アイコンでストーリー用の透過ステッカーを作れます。": "Kỷ lục cao nhất dựa trên trọng lượng thực tế (bài tập dùng trọng lượng cơ thể bao gồm cả cân nặng). Nhấn biểu tượng chia sẻ để tạo nhãn dán trong suốt cho Tin.",
  "毎日の記録、続いてます": "Ghi chép hàng ngày vẫn đang được duy trì",
  "あと{n}kcal 食べられる": "Có thể ăn thêm {n}kcal",
  "距離": "Quãng đường",
  "コピーしました": "Đã sao chép",
  "Instagramのストーリー編集画面で長押し→「ペースト」すると、写真の上にこのステッカーが載ります。": "Nhấn giữ trên màn hình chỉnh sửa Tin của Instagram -> chọn \"Dán\" để chèn nhãn dán này lên ảnh của bạn.",
  "コピーできませんでした": "Không thể sao chép",
  "「写真に保存」からお試しください。": "Vui lòng thử lại bằng cách chọn \"Lưu vào ảnh\".",
  "写真への保存が許可されていません（設定アプリ→BodyLog）。": "Không được phép lưu vào ảnh (Cài đặt -> BodyLog).",
  "写真に保存しました": "Đã lưu vào ảnh",
  "透過のまま保存されているので、ストーリーや動画編集アプリで写真の上に重ねられます。": "Ảnh được lưu dưới dạng trong suốt, bạn có thể chèn lên ảnh khác trong ứng dụng chỉnh sửa video hoặc Tin.",
  "ストーリーに共有": "Chia sẻ lên Tin",
  "文字だけの透過ステッカーです。あなたの写真の上に重ねて使えます。": "Nhãn dán trong suốt chỉ có chữ. Bạn có thể chèn lên ảnh của mình để sử dụng.",
  "白（暗い写真用）": "Trắng (cho ảnh tối màu)",
