  "食事・運動・体重を同じ日に記録する": "Ghi chép bữa ăn, vận động và cân nặng trong cùng một ngày",
  "ジムの相棒": "Bạn đồng hành phòng gym",
  "レストタイマーを累計50回使う": "Tích lũy 50 lần sử dụng bộ hẹn giờ nghỉ",
