  "21時以降の食事なしで7日間記録する": "Ghi chép 7 ngày liên tục không ăn sau 21 giờ",
  "最初の1kg": "1kg đầu tiên",
  "開始時から体重-1kg": "Giảm 1kg so với lúc bắt đầu",
  "-3kg": "-3kg",
  "開始時から体重-3kg": "Giảm 3kg so với lúc bắt đầu",
