  "くわしく記録する": "Ghi lại chi tiết",
  "広告のない、静かな画面に": "Trải nghiệm màn hình yên tĩnh, không quảng cáo",
  "ライトプラン以上で広告が消えて、記録に集中できます。": "Nâng cấp lên gói Lite trở lên để tắt quảng cáo và tập trung vào việc ghi chép.",
  "広告": "Quảng cáo",
  "ライトプランで広告を消せます": "Tắt quảng cáo với gói Lite",
  "品目つきの食事記録と翌日の体重が3組以上たまると、「あなたに合う食材・合わない食材」の傾向がここに出ます。いつもの記録を続けるだけで大丈夫です。": "Khi bạn ghi lại từ 3 bữa ăn kèm nguyên liệu và cân nặng ngày hôm sau, xu hướng \"thực phẩm hợp/không hợp với bạn\" sẽ xuất hiện ở đây. Chỉ cần tiếp tục ghi chép như thường lệ là được.",
  "いまのところ、体重をはっきり動かす食材は見つかっていません（それ自体が良い知らせです）。記録が増えると小さな傾向も見えてきます。": "Hiện tại, vẫn chưa tìm thấy loại thực phẩm nào tác động rõ rệt đến cân nặng (đó bản thân nó đã là tin vui). Khi có thêm dữ liệu ghi nhận, những xu hướng nhỏ cũng sẽ dần lộ diện.",
  "ヘルスケア連携はiOSのTestFlight版で使えます。連携すると、直近7日の歩数と睡眠がここに並びます。": "Tính năng liên kết Apple Health khả dụng trên bản TestFlight của iOS. Khi liên kết, số bước chân và giấc ngủ trong 7 ngày gần nhất sẽ hiển thị ở đây.",
  "分析を読み込めませんでした。通信状態を確認して、開き直すと再試行します。": "Không thể tải phân tích. Vui lòng kiểm tra kết nối mạng và mở lại để thử lại.",
  "まだ運動の記録がありません。運動タブで最初の1セットを記録すると、ここに{what}が育ちはじめます。": "Chưa có ghi nhận tập luyện nào. Hãy ghi lại hiệp đầu tiên trong tab Tập luyện, {what} sẽ bắt đầu phát triển ở đây.",
  "今週のサマリー": "Tổng quan tuần này",
  "からだ": "Cơ thể",
  "体の記録": "Hồ sơ cơ thể",
  "食べ方の分析": "Phân tích cách ăn uống",
  "週のふりかえり": "Tổng kết tuần",
  "運動の量": "Khối lượng vận động",
  "パッケージ裏の栄養成分表示を撮ると、表記どおりの数値で読み取れます。撮ったら↑で送信してください。": "Chụp ảnh bảng thành phần dinh dưỡng ở mặt sau bao bì để quét chính xác các chỉ số. Sau khi chụp, hãy nhấn ↑ để gửi.",
  "{date} の記録": "Nhật ký ngày {date}",
  "本気で挙げる人向け。ボリューム・目標進捗・インターバルまで全部無料で管理できます。": "Dành cho người tập nghiêm túc. Quản lý toàn bộ miễn phí từ khối lượng, tiến độ mục tiêu đến thời gian nghỉ.",
  "筋トレ履歴は「概要」タブ →「筋トレの成長」で見られます（タップで移動）": "Xem lịch sử tập ở tab \"Tổng quan\" → \"Sự phát triển cơ bắp\" (chạm để chuyển)",
  "行を長押しで削除、×でその種目だけ削除できます": "Nhấn giữ dòng để xóa, hoặc dùng × để xóa riêng bài tập đó",
  "AI相談はスタンダードから。1つの相談の中は往復無制限です": "Tư vấn AI bắt đầu từ gói Standard. Không giới hạn số lần phản hồi trong một phiên tư vấn.",
  "月額": "Hàng tháng",
  "6ヶ月": "6 tháng",
  "年額": "Hàng năm",
  "無料・ライトは最新3枚まで。スタンダード以上で図鑑のすべてが開きます。": "Gói Miễn phí và Lite chỉ xem được 3 ảnh mới nhất. Đăng ký gói Standard trở lên để mở khóa toàn bộ bách khoa toàn thư.",
  "食べ方のクセまで見える、週のふりかえり": "Nhìn lại tuần qua, thấu hiểu thói quen ăn uống",
  "1週間の食べ方をまとめて言語化。スタンダード以上で毎週のふりかえりが開きます。": "Tổng hợp và phân tích thói quen ăn uống trong tuần. Đăng ký gói Standard trở lên để mở khóa tính năng Nhìn lại hàng tuần.",
  "食べ方のクセ、ぜんぶ見える": "Thấu hiểu mọi thói quen ăn uống của bạn",
  "食べる時間帯・曜日のリズム・食材の傾向・過食の引き金。スタンダード以上で食べ方の分析が開きます。": "Khung giờ ăn, nhịp điệu ngày trong tuần, xu hướng chọn thực phẩm, tác nhân gây ăn quá nhiều. Đăng ký gói Standard trở lên để mở khóa tính năng Phân tích ăn uống.",
  "あなたの記録を読んで答える、AI相談": "Tư vấn AI, thấu hiểu qua nhật ký của bạn",
  "直近の食事・体重・栄養ログを根拠にアドバイス。スタンダード以上で使えて、1つの相談の中は往復無制限です。": "Đưa ra lời khuyên dựa trên nhật ký ăn uống, cân nặng và dinh dưỡng gần đây. Mở khóa từ gói Standard trở lên, không giới hạn số lần phản hồi trong một phiên tư vấn.",
  "今日の無料ぶんのAI解析を使い切りました": "Bạn đã dùng hết lượt phân tích AI miễn phí hôm nay",
  "明日また回復します。いま解放するなら、上のプランで1日の回数がぐっと増えます。": "Lượt dùng sẽ được khôi phục vào ngày mai. Để tiếp tục ngay bây giờ, hãy nâng cấp lên gói cao hơn để tăng số lượt dùng mỗi ngày.",
  "今日の写真解析を使い切りました": "Bạn đã dùng hết lượt phân tích ảnh hôm nay",
  "明日また回復します。いま解放するなら、写真の枚数に余裕のあるプランをどうぞ。": "Lượt dùng sẽ được khôi phục vào ngày mai. Để tiếp tục ngay bây giờ, hãy chọn gói có số lượng ảnh thoải mái hơn nhé.",
