  "注意": "Lưu ý",
  "出典": "Nguồn tham khảo",
  "タップするとアプリ内ブラウザで論文ページ（PubMed / DOI）を開きます。": "Nhấn để mở trang nghiên cứu (PubMed / DOI) bằng trình duyệt trong ứng dụng.",
  "解説記事を開く": "Mở bài viết giải thích",
  "解説を読む": "Đọc giải thích",
