  "例: 温かいもの・安く・魚がいい": "Ví dụ: Món ấm, rẻ, thích ăn cá",
  "例: 定食屋・ラーメン以外・軽め": "Ví dụ: Quán cơm bình dân, không ăn mì ramen, món nhẹ bụng",
  "例: 冷蔵庫に卵とキャベツ・20分で": "Ví dụ: Tủ lạnh có trứng và bắp cải, nấu trong 20 phút",
  "例: 甘いもの・しょっぱいもの": "Ví dụ: Món ngọt, món mặn",
  "例: 5分で・レンジだけ": "Ví dụ: Trong 5 phút, chỉ dùng lò vi sóng",
