  "残り{n}kcal": "Còn lại {n}kcal",
  "{l}残り{n}g": "{l} còn lại {n}g",
  "サラダチキン＋鮭おにぎり": "Ức gà ăn liền + Cơm nắm cá hồi",
  "たんぱく質をしっかり取りつつ、残りにゆとりが残ります。": "Bổ sung đủ protein mà vẫn dư dả lượng calo còn lại.",
  "焼き魚定食（ごはん少なめ）": "Cơm cá nướng (ít cơm)",
  "主菜でたんぱく質、ごはん少なめで残りに収まります。": "Bổ sung protein từ món chính, giảm cơm để vừa vặn với lượng calo còn lại.",
  "鶏むねの照り焼き・ほうれん草のおひたし・ごはん150g": "Ức gà sốt teriyaki + Cải bó xôi luộc + 150g cơm",
  "主菜・副菜・主食がそろい、20分で作れます。": "Đầy đủ món chính, món phụ, món tinh bột và chỉ mất 20 phút chế biến.",
  "ギリシャヨーグルト＋バナナ半分": "Sữa chua Hy Lạp + Nửa quả chuối",
  "200kcal以内で、小腹と甘いもの欲を同時に満たせます。": "Dưới 200kcal, vừa giải quyết cơn đói nhẹ vừa thỏa mãn cơn thèm ngọt.",
  "ゆで卵2個＋バナナ": "2 quả trứng luộc + Chuối",
  "買ってそのまま食べられて、たんぱく質も確保できます。": "Mua ăn được ngay mà vẫn đảm bảo lượng protein cần thiết.",
  "栄養ランキング": "Bảng xếp hạng dinh dưỡng",
  "◯◯が多い食材・かしこい置き換え・たんぱく源ティア": "Thực phẩm giàu chất dinh dưỡng • Đổi món thông minh • Xếp hạng nguồn đạm",
  "置き換え候補を見る": "Xem gợi ý thay thế",
  "かしこい置き換え": "Đổi món thông minh",
  "たんぱく源のうちAティア以上の割合（たんぱく質g加重）": "Tỷ lệ nguồn đạm từ hạng A trở lên (tính theo g đạm)",
  "直近30日の{n}食のたんぱく源から（{mode}の基準）": "Dựa trên {n} bữa ăn có đạm trong 30 ngày qua (tiêu chuẩn {mode})",
  "Aティア以上": "Từ hạng A trở lên",
  "Bティア以下": "Từ hạng B trở xuống",
  "この栄養素で、より少ないカロリーの候補は見つかりませんでした。": "Không tìm thấy món thay thế ít calo hơn cho chất dinh dưỡng này.",
  "日本の一般食材 約{n}品の目安値（日本食品標準成分表 八訂ベース）。同じ栄養をより少ないカロリーで取る「かしこい置き換え」も見られます。": "Ước tính từ khoảng {n} thực phẩm phổ biến tại Nhật Bản (theo Bảng thành phần thực phẩm Nhật Bản tái bản lần 8). Bạn cũng có thể xem mục \"Đổi món thông minh\" để nạp cùng lượng dinh dưỡng với ít calo hơn.",
  "「{name}」の置き換え候補": "Gợi ý thay thế cho \"{name}\"",
  "この品目は食材の辞書に無いため、置き換え候補を出せません。": "Món này không có trong từ điển thực phẩm nên không thể gợi ý món thay thế.",
  "ランキング": "Bảng xếp hạng",
  "たんぱく源": "Nguồn đạm",
  "1食の目安量あたり": "Mỗi khẩu phần ước tính",
  "100gあたり": "Mỗi 100g",
  "{x}が多い食材 TOP10": "TOP 10 thực phẩm giàu {x}",
  "{g}g（{u}）": "{g}g ({u})",
  "{x}なら、この食材の代わりに": "Để nạp {x}, hãy thử thay cho món này",
  "減量の基準": "Tiêu chuẩn giảm cân",
  "増量の基準": "Tiêu chuẩn tăng cân",
  "たんぱく質1gあたりのkcal・脂質の割合・つい量が増えやすいか・手間・価格帯で格付け。": "Xếp hạng dựa trên: kcal/1g đạm, tỷ lệ chất béo, dễ ăn quá đà, độ tiện lợi và mức giá.",
  "100gあたりのたんぱく質とkcal密度・食べやすさ・手間・価格帯で格付け。": "Xếp hạng dựa trên: lượng đạm & mật độ kcal trên 100g, độ dễ ăn, độ tiện lợi và mức giá.",
  "色つきのチップは直近30日に食べたもの。": "Các thẻ có màu là món bạn đã ăn trong 30 ngày qua.",
  "100gあたり {k}kcal・P{p}g・F{f}g・1食の目安 {s}g": "Mỗi 100g: {k}kcal • P{p}g • F{f}g • 1 khẩu phần khoảng {s}g",
  "数値は目安です。品種・部位・調理で20〜30%は変わります。格付けは「同じたんぱく質量あたりのカロリー」を軸にした並びで、食材の善悪ではありません。": "Số liệu chỉ mang tính tham khảo, có thể chênh lệch 20–30% tùy loại, phần thịt hay cách chế biến. Xếp hạng dựa trên \"lượng calo cho cùng một lượng đạm\", không phản ánh thực phẩm tốt hay xấu.",
  "◯◯が多いのは？食材ランキング": "Thực phẩm nào giàu chất này? Xem BXH",
  "鉄・ビタミン・亜鉛…が多い食材と、同じ栄養をより少ないカロリーで取る「かしこい置き換え」。たんぱく源のティア表も": "Thực phẩm giàu sắt, vitamin, kẽm... và gợi ý \"Đổi món thông minh\" để nạp đủ chất với ít calo hơn. Kèm bảng xếp hạng nguồn đạm tiện lợi",
  "置き換えるなら": "Gợi ý thay thế",
