  "たんぱく源の選び方のこと": "Cách chọn nguồn đạm",
  "あなたのたんぱく源はAティア以上が{p}%": "Nguồn đạm của bạn có {p}% đạt từ hạng A trở lên",
  "{food}（{tier}ティア）を{best}（S）に替えると1食あたり約−{n}kcal": "Đổi {food} (hạng {tier}) sang {best} (S) giúp giảm khoảng {n} kcal mỗi bữa",
  "{x}なら、{b}で{a}ぶん": "Với {x}, thì {b} tương đương {a}",
